/* 测试用的 obsidian mock（仅用于 Node 冒烟测试，不进插件包） */

class MockEl {
  constructor(tag) {
    this.tag = tag || 'div';
    this.children = [];
    this.classList = new Set();
    this.cls = '';
    this.style = {};
    this.attrs = {};
    this.text = '';
    this.onclick = null;
  }
  _mk(tag) {
    const el = new MockEl(tag);
    this.children.push(el);
    return el;
  }
  createDiv(o) { return this._apply(this._mk('div'), o); }
  createSpan(o) { return this._apply(this._mk('span'), o); }
  createEl(tag, o) {
    const el = this._apply(this._mk(tag), o);
    if (o && o.attr) Object.assign(el.attrs, o.attr);
    if (o && o.type) el.type = o.type;
    return el;
  }
  _apply(el, o) {
    o = o || {};
    if (o.cls) {
      el.cls = o.cls;
      o.cls.split(' ').forEach((c) => c && el.classList.add(c));
    }
    if (o.text !== undefined) el.text = o.text;
    return el;
  }
  /*
   * 与真实 DOM 保持一致：DOMTokenList.add 不接受含空格的 token，
   * 传 'a b' 会抛 InvalidCharacterError。
   * mock 早期用 Set 实现，不报错，导致这类 bug 在测试里漏检、
   * 到了真实环境才炸（面板渲染成空白）。这里显式复现该行为。
   */
  addClass(c) {
    if (String(c).indexOf(' ') !== -1) {
      throw new Error('InvalidCharacterError: token contains space: ' + c);
    }
    this.classList.add(c);
    if (this.cls.indexOf(c) === -1) this.cls = (this.cls + ' ' + c).trim();
    return this;
  }
  removeClass(c) { this.classList.delete(c); this.cls = this.cls.split(' ').filter((x) => x && x !== c).join(' '); return this; }
  toggleClass(c, on) { return on ? this.addClass(c) : this.removeClass(c); }
  hasClass(c) { return this.classList.has(c); }
  setText(t) { this.text = String(t); return this; }
  /** 递归聚合全部文本，供测试断言 */
  get textContent() {
    let out = this.text ? String(this.text) : '';
    (this.children || []).forEach((c) => {
      if (typeof c.textContent === 'string') out += c.textContent;
    });
    return out;
  }
  empty() { this.children = []; return this; }
  appendChild(el) { this.children.push(el); return el; }
  remove() {}
  setAttribute(k, v) { this.attrs[k] = v; }
  getAttribute(k) { return this.attrs[k]; }
  removeAttribute(k) { delete this.attrs[k]; }
  addEventListener() {}
  getBoundingClientRect() { return { left: 800, top: 400, width: 208, height: 160 }; }
}

class Plugin {
  constructor(app, manifest) { this.app = app; this.manifest = manifest; this._data = null; }
  addRibbonIcon() { return new MockEl('div'); }
  addCommand(c) { (this.commands = this.commands || []).push(c); return c; }
  addSettingTab(t) { (this.tabs = this.tabs || []).push(t); return t; }
  addStatusBarItem() { return new MockEl('div'); }
  registerView() {}
  registerEditorSuggest() {}
  registerInterval() {}
  registerEvent() {}
  async loadData() { return this._data; }
  async saveData(d) { this._data = d; }
}
class ItemView { constructor(leaf) { this.leaf = leaf; this.contentEl = new MockEl('div'); } registerInterval() {} }
class EditorSuggest { constructor(app) { this.app = app; } }
class PluginSettingTab { constructor(app, plugin) { this.app = app; this.plugin = plugin; this.containerEl = new MockEl('div'); } }
/*
 * Modal：补齐真实 Modal 的 setTitle / setContent。
 * mock 原先缺这两个方法，confirmDialog 一调用就抛错 ——
 * 而沙盒里根本跑不到确认弹窗，等于这块逻辑一直没被测过。
 */
class Modal {
  constructor(app) {
    this.app = app;
    this.contentEl = new MockEl('div');
    this.title = '';
    global.__currentModal = this;
  }
  setTitle(t) { this.title = String(t); return this; }
  setContent(c) { this.content = String(c); this.contentEl.setText(this.content); return this; }
  open() {
    global.__modals.push(this);
    this.onOpen && this.onOpen();
    /*
     * 测试辅助：__autoAnswer 设为 'ok' / 'cancel' 时自动点对应按钮。
     * confirmDialog 先建「取消」再建「确定」，所以 cancel=首个、ok=末个。
     */
    const want = global.__autoAnswer;
    if (!want) return;
    const btns = (global.__buttons || []).filter((b) => b.modal === this);
    const target = want === 'ok' ? btns[btns.length - 1] : btns[0];
    if (target && typeof target.click === 'function') target.click();
  }
  close() { this.onClose && this.onClose(); }
}

/*
 * ButtonComponent：真实 Obsidian 有，mock 原先没有 ——
 * confirmDialog 里的按钮因此在沙盒里无法构造。
 */
class ButtonComponent {
  constructor(el) {
    this.el = el;
    this.text = '';
    this.cta = false;
    this.warning = false;
    this.click = null;
    this.modal = global.__currentModal || null;
    (global.__buttons = global.__buttons || []).push(this);
  }
  setButtonText(t) { this.text = String(t); return this; }
  setCta() { this.cta = true; return this; }
  setWarning() { this.warning = true; return this; }
  setDisabled(v) { this.disabled = !!v; return this; }
  onClick(fn) { this.click = fn; return this; }
}
class Notice { constructor(msg) { global.__notices.push(msg); } }
class Setting {
  constructor(el) {
    this.settingEl = new MockEl('div');
    /*
     * 真实 Setting 会把自身挂进传入的容器；mock 原先忽略 el，
     * 导致「某项设置渲染进了哪个容器」无从验证 ——
     * 而折叠区正是靠这一点判断的（关总开关后设置应在 details 内）。
     */
    if (el && Array.isArray(el.children)) el.children.push(this.settingEl);
    this.hostEl = el || null;
    this.name = '';
    this.desc = '';
    this.components = [];
    (global.__settings = global.__settings || []).push(this);
  }
  setName(n) { this.name = n; return this; }
  setDesc(d) { this.desc = d; return this; }
  _comp() {
    const c = {
      value: undefined,
      setValue(v) { c.value = v; return c; },
      setPlaceholder() { return c; },
      setButtonText(t) { c.text = t; return c; },
      addOption(k, v) { (c.options = c.options || {})[k] = v; return c; },
      onChange(fn) { c.change = fn; return c; },
      onClick(fn) { c.click = fn; return c; },
      setCta() { return c; },
      setDisabled() { return c; },
      setWarning() { return c; },
    };
    this.components.push(c);
    return c;
  }
  addText(cb) { cb(this._comp()); return this; }
  addToggle(cb) { cb(this._comp()); return this; }
  addDropdown(cb) { cb(this._comp()); return this; }
  addTextArea(cb) { cb(this._comp()); return this; }
  addButton(cb) { cb(this._comp()); return this; }
}
class MarkdownView {}

function moment(ts) {
  const d = ts === undefined ? new Date() : new Date(ts);
  return {
    format(fmt) {
      const pad = (n) => String(n).padStart(2, '0');
      const Y = String(d.getFullYear());
      const M = pad(d.getMonth() + 1);
      const D = pad(d.getDate());
      const H = pad(d.getHours());
      const m = pad(d.getMinutes());
      const S = pad(d.getSeconds());
      if (fmt === 'HH:mm') return H + ':' + m;
      if (fmt === 'YYYY-MM-DD') return `${Y}-${M}-${D}`;
      if (fmt === 'YYYY-MM-DD HH:mm') return `${Y}-${M}-${D} ${H}:${m}`;
      if (fmt === 'YYYY-MM-DD HH:mm:ss') return `${Y}-${M}-${D} ${H}:${m}:${S}`;
      if (fmt === 'HH:mm:ss') return `${H}:${m}:${S}`;
      // 星期：真实 moment 有 ddd/dddd（随 locale，中文下为「周一」/「星期一」）。
      // mock 原先不支持，导致含 ddd 的格式串测不出真实结果（如兼容的 DI）。
      // dddd 必须先于 ddd 替换，否则会被 ddd 抢先匹配。
      const WK = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
      const w = d.getDay();
      // 通用兜底：按 token 逐个替换，够测试用
      return String(fmt)
        .replace(/dddd/g, '星期' + WK[w]).replace(/ddd/g, WK[w])
        .replace(/YYYY/g, Y).replace(/MM/g, M).replace(/DD/g, D)
        .replace(/HH/g, H).replace(/mm/g, m).replace(/ss/g, S);
    },
  };
}

// 官方 API：给元素设置内置图标（渲染为 SVG）
function setIcon(el, icon) {
  if (!el) return;
  if (typeof el.setAttribute === 'function') el.setAttribute('data-icon', icon);
  if (typeof el.addClass === 'function') el.addClass('tt-icon');
  el.icon = icon;
}

/** 路径归一化：与 Obsidian 官方行为对齐（测试用，不进插件包）
 *  忠实模拟真实实现 —— 不许写成 (p)=>p，那会把错误用法固化成"通过"的断言。 */
function normalizePath(p) {
  const s = String(p == null ? '' : p);
  if (!s) return '';                       // ← 空串必须保空（留空＝库根目录）
  return s
    .replace(/\\/g, '/')                   // 反斜杠 → 正斜杠
    .replace(/\/+/g, '/')                  // 连续斜杠合并
    .replace(/^\/+/, '')                   // 去前导斜杠
    .replace(/\/+$/, '');                  // 去尾随斜杠
}

module.exports = {
  Plugin, ItemView, EditorSuggest, PluginSettingTab, Modal, Notice, Setting, setIcon,
  ButtonComponent,
  MarkdownView, moment,
  normalizePath,
  Platform: { isMobile: false },
  MockEl,
};


// 沙盒没有 DOM：补最小 document/window stub，避免注册路径误报
if (typeof global.document === 'undefined') {
  const listeners = {};
  global.document = {
    addEventListener() {}, removeEventListener() {},
    createElement: () => ({ style: {}, classList: { add(){}, remove(){} }, appendChild(){}, setAttribute(){} }),
    body: { appendChild(){}, classList: { add(){}, remove(){} } },
  };
}
if (typeof global.window === 'undefined') {
  global.window = { addEventListener() {}, removeEventListener() {}, setTimeout, clearTimeout };
}
